{
  "returncode": 0,
  "output_head": "//! Quizzy — a live quiz for conference talks. This is the moderator release:
//! preparing quizzes, questions and options, plus a playable preview.
//!
//! Run with: PORT=3000 SECRET_KEY_BASE=... QUIZZY_MODERATOR_USERNAME=... \
//!           QUIZZY_MODERATOR_PASSWORD=... ./bin/serve
//!
//! SECRET_KEY_BASE is accepted for forward compatibility (session signing in
//! later releases); this release keeps no session state.

mod db;
mod httpd;
mod routes;
mod views;

use std::sync::Arc;

fn main() {
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(3000);
    let state = Arc::new(routes::State {
        db_path: std::env::var("QUIZZY_DATABASE_PATH")
            .unwrap_or_else(|_| "storage/quizzy.db".to_string()),
        moderator_username: std::env::var("QUIZZY_MODERATOR_USERNAME").unwrap_or_default(),
        moderator_password: std::env::var("QUIZZY_MODERATOR_PASSWORD").unwrap_or_default(),
    });

    // Everything the app stores lives under storage/.
    if let Some(parent) = std::path::Path::new(&state.db_path).parent() {
        std::fs::create_dir_all(parent).expect("cannot create storage directory");
    }
    {
        let conn = db::connect(&state.db_path).expect("cannot open the database");
        db::migrate(&conn).expect("cannot migrate the database");
    }

    let server = tiny_http::Server::http(("0.0.0.0", port))
        .unwrap_or_else(|e| panic!("cannot listen on port {port}: {e}"));
    println!("Quizzy is ready on http://0.0.0.0:{port}");
    let server = Arc::new(server);

    let workers = std::thread::available_parallelism().map(|n| n.get().clamp(8, 32)).unwrap_or(8);
    let mut handles = Vec::new();
    for _ in 0..workers {
        let server = Arc::clone(&server);
        let state = Arc::clone(&state);
        handles.push(std::thread::spawn(move || loop {
            match server.recv() {
                Ok(request) => {
                    let state = Arc::clone(&state);
                    httpd::dispatch(request, &move |req| routes::handle(req, &state));
                }
                Err(_) => continue,
            }
        }));
    }
    for h in handles {
        let _ = h.join();
    }
}
//! SQLite storage for Quizzy.
//!
//! Schema: quizzes have questions (ordered by `position`), questions have
//! options (ordered by `position`). Deleting a quiz cascades to its questions
//! and options through foreign keys.

use rusqlite::{Connection, Result, params};

#[derive(Debug, Clone)]
pub struct Quiz {
    pub id: i64,
    pub title: String,
}

#[derive(Debug, Clone)]
pub struct Question {
    pub id: i64,
    pub quiz_id: i64,
    pub position: i64,
    pub text: String,
    pub active: bool,
    pub options: Vec<Opt>,
}

#[derive(Debug, Clone)]
pub struct Opt {
    pub id: i64,
    pub text: String,
    pub correct: bool,
}

pub struct QuizSummary {
    pub quiz: Quiz,
    pub total_questions: i64,
    pub active_questions: i64,
}

/// Open a connection with the pragmas every connection needs.
pub fn connect(path: &str) -> Result<Connection> {
    let conn = Connection::open(path)?;
    conn.execute_batch(
        "PRAGMA foreign_keys = ON;
         PRAGMA busy_timeout = 5000;",
    )?;
    Ok(conn)
}

/// Create the schema if it does not exist yet. Safe to run on every boot.
pub fn migrate(conn: &Connection) -> Result<()> {
    conn.execute_batch(
        "PRAGMA journal_mode = WAL;

         CREATE TABLE IF NOT EXISTS quizzes (
           id         INTEGER PRIMARY KEY AUTOINCREMENT,
           title      TEXT NOT NULL,
           created_at TEXT NOT NULL DEFAULT (datetime('now'))
         );

         CREATE TABLE IF NOT EXISTS questions (
           id       INTEGER PRIMARY KEY AUTOINCREMENT,
           quiz_id  INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
           position INTEGER NOT NULL,
           text     TEXT NOT NULL,
           active   INTEGER NOT NULL DEFAULT 1
         );
         CREATE INDEX IF NOT EXISTS idx_questions_quiz ON questions(quiz_id, position);

         CREATE TABLE IF NOT EXISTS options (
           id          INTEGER PRIMARY KEY AUTOINCREMENT,
           question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
           position    INTEGER NOT NULL,
           text        TEXT NOT NULL,
           correct     INTEGER NOT NULL DEFAULT 0
         );
         CREATE INDEX IF NOT EXISTS idx_options_question ON options(question_id, position);",
    )?;
    Ok(())
}

// ---------- Quizzes ----------

pub fn list_quizzes(conn: &Connection) -> Result<Vec<QuizSummary>> {
    let mut stmt = conn.prepare(
        "SELECT q.id, q.title,
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id),
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id AND active = 1)
         FROM quizzes q ORDER BY q.id",
    )?;
    let rows = stmt.query_map([], |row| {
        Ok(QuizSummary {
            quiz: Quiz { id: row.get(0)?, title: ro",
  "output_tail": "uiz { id: row.get(0)?, title: row.get(1)? })),
        None => Ok(None),
    }
}

pub fn update_quiz(conn: &Connection, id: i64, title: &str) -> Result<()> {
    conn.execute("UPDATE quizzes SET title = ?2 WHERE id = ?1", params![id, title])?;
    Ok(())
}

pub fn delete_quiz(conn: &Connection, id: i64) -> Result<()> {
    conn.execute("DELETE FROM quizzes WHERE id = ?1", params![id])?;
    Ok(())
}

// ---------- Questions ----------

pub fn list_questions(conn: &Connection, quiz_id: i64) -> Result<Vec<Question>> {
    let mut stmt = conn.prepare(
        "SELECT id, quiz_id, position, text, active FROM questions
         WHERE quiz_id = ?1 ORDER BY position, id",
    )?;
    let rows = stmt.query_map(params![quiz_id], |row| {
        Ok(Question {
            id: row.get(0)?,
            quiz_id: row.get(1)?,
            position: row.get(2)?,
            text: row.get(3)?,
            active: row.get::<_, i64>(4)? != 0,
            options: Vec::new(),
        })
    })?;
    let mut questions: Vec<Question> = rows.collect::<Result<_>>()?;
    for q in &mut questions {
        q.options = list_options(conn, q.id)?;
    }
    Ok(questions)
}

pub fn get_question(conn: &Connection, id: i64) -> Result<Option<Question>> {
    let mut stmt =
        conn.prepare("SELECT id, quiz_id, position, text, active FROM questions WHERE id = ?1")?;
    let mut rows = stmt.query(params![id])?;
    match rows.next()? {
        Some(row) => {
            let mut q = Question {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                position: row.get(2)?,
                text: row.get(3)?,
                active: row.get::<_, i64>(4)? != 0,
                options: Vec::new(),
            };
            q.options = list_options(conn, q.id)?;
            Ok(Some(q))
        }
        None => Ok(None),
    }
}

fn list_options(conn: &Connection, question_id: i64) -> Result<Vec<Opt>> {
    let mut stmt = conn.prepare(
        "SELECT id, text, correct FROM options WHERE question_id = ?1 ORDER BY position, id",
    )?;
    let rows = stmt.query_map(params![question_id], |row| {
        Ok(Opt { id: row.get(0)?, text: row.get(1)?, correct: row.get::<_, i64>(2)? != 0 })
    })?;
    rows.collect()
}

/// `options` is a list of (text, correct) pairs in display order.
pub fn create_question(
    conn: &Connection,
    quiz_id: i64,
    text: &str,
    active: bool,
    options: &[(String, bool)],
) -> Result<i64> {
    let position: i64 = conn.query_row(
        "SELECT COALESCE(MAX(position), 0) + 1 FROM questions WHERE quiz_id = ?1",
        params![quiz_id],
        |row| row.get(0),
    )?;
    conn.execute(
        "INSERT INTO questions (quiz_id, position, text, active) VALUES (?1, ?2, ?3, ?4)",
        params![quiz_id, position, text, active as i64],
    )?;
    let id = conn.last_insert_rowid();
    insert_options(conn, id, options)?;
    Ok(id)
}

/// Replace text/active/options of an existing question (position untouched).
pub fn update_question(
    conn: &Connection,
    id: i64,
    text: &str,
    active: bool,
    options: &[(String, bool)],
) -> Result<()> {
    conn.execute(
        "UPDATE questions SET text = ?2, active = ?3 WHERE id = ?1",
        params![id, text, active as i64],
    )?;
    conn.execute("DELETE FROM options WHERE question_id = ?1", params![id])?;
    insert_options(conn, id, options)?;
    Ok(())
}

fn insert_options(conn: &Connection, question_id: i64, options: &[(String, bool)]) -> Result<()> {
    let mut stmt =
        conn.prepare("INSERT INTO options (question_id, position, text, correct) VALUES (?1, ?2, ?3, ?4)")?;
    for (i, (text, correct)) in options.iter().enumerate() {
        stmt.execute(params![question_id, (i + 1) as i64, text, *correct as i64])?;
    }
    Ok(())
}

pub fn delete_question(conn: &Connection, id: i64) -> Result<()> {
    conn.execute("DELETE FROM questions WHERE id = ?1", params![id])?;
    Ok(())
}

pub fn set_question_active(conn: &Connection, id: i64, active: bool) -> Result<()> {
    conn.execute("UPDATE questions SET active = ?2 WHERE id = ?1", params![id, active as i64])?;
    Ok(())
}

/// Swap a question with its neighbour in the quiz's ordering.
pub fn move_question(conn: &Connection, id: i64, dir: &str) -> Result<()> {
    let Some(q) = get_question(conn, id)? else { return Ok(()) };
    let questions = list_questions(conn, q.quiz_id)?;
    let Some(idx) = questions.iter().position(|x| x.id == id) else { return Ok(()) };
    let other = match dir {
        "up" => idx.checked_sub(1),
        "down" => {
            if idx + 1 < questions.len() { Some(idx + 1) } else { None }
        }
        _ => None,
    };
    if let Some(o) = other {
        let a = &questions[idx];
        let b = &questions[o];
        conn.execute("UPDATE questions SET position = ?2 WHERE id = ?1", params![a.id, b.position])?;
        conn.execute("UPDATE questions SET position = ?2 WHERE id = ?1", params![b.id, a.position])?;
    }
    Ok(())
}
