use crate::db::{self, Question};
use crate::httpd::{Request, Resp, basic_credentials};
use crate::views;
use rusqlite::Connection;

pub struct State {
    pub db_path: String,
    pub moderator_username: String,
    pub moderator_password: String,
}

const CSS: &str = include_str!("../assets/quizzy.css");
const FONT: &[u8] = include_bytes!("../assets/Inter-latin.woff2");

pub fn handle(req: &Request, state: &State) -> Resp {
    let segments: Vec<&str> = req.path.split('/').filter(|s| !s.is_empty()).collect();
    match (req.method.as_str(), segments.as_slice()) {
        ("GET", ["up"]) => return Resp::text(200, "OK"),
        ("GET", []) => return Resp::redirect("/moderate"),
        ("GET", ["assets", "quizzy.css"]) => {
            return Resp { status: 200, content_type: "text/css; charset=utf-8", body: CSS.as_bytes().to_vec(), extra_headers: vec![] };
        }
        ("GET", ["assets", "Inter-latin.woff2"]) => {
            return Resp { status: 200, content_type: "font/woff2", body: FONT.to_vec(), extra_headers: vec![] };
        }
        ("GET", ["favicon.ico"]) => return Resp { status: 204, content_type: "image/x-icon", body: vec![], extra_headers: vec![] },
        _ => {}
    }
    // Everything else lives in the moderator area and needs authentication.
    if !authorized(req, state) {
        return Resp::unauthorized();
    }
    let conn = match db::connect(&state.db_path) {
        Ok(c) => c,
        Err(_) => return Resp::text(500, "Database error"),
    };
    moderate(req, &conn, &segments)
}

fn authorized(req: &Request, state: &State) -> bool {
    let Some(header) = &req.authorization else { return false };
    let Some((user, pass)) = basic_credentials(header) else { return false };
    user == state.moderator_username && pass == state.moderator_password
}

fn parse_id(s: &str) -> Option<i64> {
    s.parse::<i64>().ok().filter(|id| *id > 0)
}

fn moderate(req: &Request, conn: &Connection, segs: &[&str]) -> Resp {
    match (req.method.as_str(), segs) {
        // ---------- Quizzes ----------
        ("GET", ["moderate"]) => {
            let summaries = db::list_quizzes(conn).unwrap_or_default();
            Resp::html(views::quiz_list(&summaries))
        }
        ("GET", ["moderate", "quizzes", "new"]) => {
            Resp::html(views::quiz_form(None, "", &[]))
        }
        ("POST", ["moderate", "quizzes"]) => {
            let title = req.param("title").unwrap_or("").trim().to_string();
            if title.is_empty() {
                return Resp::html(views::quiz_form(None, "", &["Enter a title".to_string()]));
            }
            let id = db::create_quiz(conn, &title).map_err(|_| ()).unwrap_or(0);
            Resp::redirect(&format!("/moderate/quizzes/{id}"))
        }
        ("GET", ["moderate", "quizzes", id]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let questions = db::list_questions(conn, id).unwrap_or_default();
            Resp::html(views::quiz_page(&quiz, &questions))
        }
        ("GET", ["moderate", "quizzes", id, "edit"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            Resp::html(views::quiz_form(Some(&quiz), &quiz.title, &[]))
        }
        ("POST", ["moderate", "quizzes", id]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let title = req.param("title").unwrap_or("").trim().to_string();
            if title.is_empty() {
                return Resp::html(views::quiz_form(Some(&quiz), "", &["Enter a title".to_string()]));
            }
            let _ = db::update_quiz(conn, id, &title);
            Resp::redirect(&format!("/moderate/quizzes/{id}"))
        }
        ("POST", ["moderate", "quizzes", id, "delete"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let _ = db::delete_quiz(conn, id);
            Resp::redirect("/moderate")
        }
        // ---------- Questions ----------
        ("GET", ["moderate", "quizzes", id, "questions", "new"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let rows = vec![
                views::OptionRow { text: String::new(), correct: false },
                views::OptionRow { text: String::new(), correct: false },
                views::OptionRow { text: String::new(), correct: false },
                views::OptionRow { text: String::new(), correct: false },
            ];
            let action = format!("/moderate/quizzes/{id}/questi",
  "output_tail": ".param("dir").unwrap_or("").to_string();
            let _ = db::move_question(conn, qid, &dir);
            Resp::redirect(&format!("/moderate/quizzes/{id}"))
        }
        ("POST", ["moderate", "quizzes", id, "questions", qid, "active"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(qid) = parse_id(qid) else { return Resp::not_found() };
            let _ = db::set_question_active(conn, qid, req.has_param("active"));
            Resp::redirect(&format!("/moderate/quizzes/{id}"))
        }
        // ---------- Preview ----------
        ("GET", ["moderate", "quizzes", id, "preview"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let questions = active_questions(conn, id);
            if questions.is_empty() {
                return Resp::html(views::preview_empty(&quiz));
            }
            let total = questions.len();
            let n = req.param("n").and_then(|v| v.parse::<usize>().ok()).unwrap_or(1).clamp(1, total);
            let score = req.param("score").and_then(|v| v.parse::<i64>().ok()).unwrap_or(0).clamp(0, total as i64);
            Resp::html(views::preview_question(&quiz, &questions[n - 1], n, total, score))
        }
        ("POST", ["moderate", "quizzes", id, "preview", "answer"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let questions = active_questions(conn, id);
            if questions.is_empty() {
                return Resp::html(views::preview_empty(&quiz));
            }
            let total = questions.len();
            let n = req.param("n").and_then(|v| v.parse::<usize>().ok()).unwrap_or(1);
            let score = req.param("score").and_then(|v| v.parse::<i64>().ok()).unwrap_or(0);
            let base = format!("/moderate/quizzes/{id}/preview");
            if n < 1 || n > total {
                return Resp::redirect(&base);
            }
            let q = &questions[n - 1];
            let option_id = req.param("option").and_then(parse_id);
            let Some(opt) = option_id.and_then(|oid| q.options.iter().find(|o| o.id == oid)) else {
                // Unknown option: just show the question again.
                return Resp::redirect(&format!("{base}?n={n}&score={score}"));
            };
            let new_score = (score + if opt.correct { 1 } else { 0 }).clamp(0, total as i64);
            Resp::html(views::preview_feedback(&quiz, q, n, total, opt.id, opt.correct, new_score))
        }
        ("GET", ["moderate", "quizzes", id, "preview", "score"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let total = active_questions(conn, id).len();
            let score = req.param("score").and_then(|v| v.parse::<i64>().ok()).unwrap_or(0).clamp(0, total as i64);
            Resp::html(views::preview_score(&quiz, score, total))
        }
        _ => Resp::not_found(),
    }
}

fn active_questions(conn: &Connection, quiz_id: i64) -> Vec<Question> {
    db::list_questions(conn, quiz_id)
        .unwrap_or_default()
        .into_iter()
        .filter(|q| q.active)
        .collect()
}

struct QuestionForm {
    text: String,
    rows: Vec<views::OptionRow>,
    active: bool,
}

fn read_question_form(req: &Request) -> QuestionForm {
    let count: usize = req.param("option_count").and_then(|v| v.parse().ok()).unwrap_or(0).min(100);
    let mut rows = Vec::with_capacity(count);
    for i in 1..=count {
        rows.push(views::OptionRow {
            text: req.param(&format!("option_text_{i}")).unwrap_or("").to_string(),
            correct: req.has_param(&format!("option_correct_{i}")),
        });
    }
    QuestionForm {
        text: req.param("question").unwrap_or("").to_string(),
        rows,
        active: req.has_param("active"),
    }
}

/// Apply the option rules. Returns the cleaned options or the error messages
/// to show above the form (nothing is saved in that case).
fn validate_question(form: &QuestionForm) -> Result<Vec<(String, bool)>, Vec<String>> {
    let mut errors = Vec::new();
    if form.text.trim().is_empty() {
        errors.push("Enter the question text".to_string());
    }
    let filled: Vec<&views::OptionRow> = form.rows.iter().filter(|r| !r.text.trim().is_empty()).collect();
    if filled.len() < 2 {
        errors.push("Add at least two options".to_string());
    }
    if !filled.iter().any(|r| r.correct) {
        errors.push("Mark at least one option as correct".to_string());
    }
    if errors.is_empty() {
        Ok(filled.iter().map(|r| (r.text.trim().to_string(), r.correct)).collect())
    } else {
        Err(errors)
    }
}
