```rust
pub fn parse(input: &str) -> Result<Value, String> {
    let mut p = Parser { chars: input.as_bytes(), pos: 0, input };
    p.skip_ws();
    let value = p.value()?;
    p.skip_ws();
    if p.pos < p.bytes.len() { return Err(format!("unexpected character at byte {}", p.pos)); }
    Ok(value)
}

struct Parser<'a> { s: &'a [u8], pos: usize }
```

