```rust
fn string(&mut self) -> Result<String, String> {
    // assumes current byte is '"'
    self.pos += 1;
    let mut out = String::new();
    loop {
        match self.next_byte() {
            None => return Err("unterminated string".into()),
            Some(b'"') => return Ok(out),
            Some(b'\\') => {
                match self.next_byte() {
                    Some(b'"') => out.push('"'),
                    Some(b'\\') => out.push('\\'),
                    Some(b'/') => out.push('/'),
                    Some(b'b') => out.push('\u{0008}'),
                    Some(b'f') => out.push('\u{000C}'),
                    Some(b'n') => out.push('\n'),
                    Some(b'r') => out.push('\r'),
                    Some(b't') => out.push('\t'),
                    Some(b'u') => {
                        let cp = self.hex4()?;
                        if (0xD800..0xDC00).contains(&cp) {
                            // high surrogate; expect \uXXXX low
                            if self.next_byte() != Some(b'\\') || self.next_byte() != Some(b'u') {
                                return Err("lone surrogate in string".into());
                            }
                            let lo = self.hex4()?;
                            if !(0xDC00..0xE000).contains(&lo) { return Err("invalid surrogate pair".into()); }
                            let c = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            out.push(char::from_u32(c).ok_or("invalid code point")?);
                        } else if (0xDC00..0xE000).contains(&cp) {
                            return Err("lone surrogate in string".into());
                        } else {
                            out.push(char::from_u32(cp).ok_or("invalid code point")?);
                        }
                    }
                    _ => return Err("invalid escape".into()),
                }
            }
            Some(c) if c < 0x20 => return Err("control character in string".into()),
            Some(c) => {
                // collect UTF-8 sequence as-is; input is &str so bytes are valid UTF-8
                out.push(c as char)  // NO — this breaks multi-byte!
            }
        }
    }
}
```

Careful: iterating bytes of a &str — multi-byte UTF-8 chars would be pushed incorrectly with `c as char`. Instead, for bytes >= 0x80 I need to reconstruct. Better approach: find string segments. Alternative: operate on `char_indices`? Simpler: since input is `&str`, I can take slices. Approach: keep `start` marker; when I hit a special char (`"` or `\` or control), push the slice from start..pos, then handle. Let me restructure:

```rust
fn string(&mut self) -> Result<String, String> {
    self.pos += 1; // opening quote
    let mut out = String::new();
    let mut start = self.pos;
    loop {
        let Some(&b) = self.s.get(self.pos) else { return Err("unterminated string".into()) };
        match b {
            b'"' => {
                out.push_str(std::str::from_utf8(&self.s[start..self.pos]).map_err(|_| "invalid UTF-8".to_string())?);
                self.pos += 1;
                return Ok(out);
            }
            b'\\' => {
                out.push_str(str::from_utf8(&self.s[start..self.pos])...?);
                self.pos += 1;
                ... handle escape, which may push chars ...
                start = self.pos;
            }
            0x00..=0x1F => return Err("control character in string".into()),
            _ => { self.pos += 1; }
        }
    }
}
```

Since the input came from a &str, slices at arbitrary byte boundaries could split a UTF-8 char? No — we only cut at positions of `"` or `\` which are ASCII, so boundaries are always on char boundaries. from_utf8 will succeed. Good.

