fn hex4(&mut self) -> Result<u32, String> {
    let mut v = 0u32;
    for _ in 0..4 {
        let b = self.s.get(self.pos).copied().ok_or("unterminated \\u escape")?;
        let d = match b { b'0'..=b'9' => b - b'0', b'a'..=b'f' => b - b'a' + 10, b'A'..=b'F' => b - b'A' + 10, _ => return Err("invalid \\u escape".into()) };
        v = v * 16 + d as u32;
        self.pos += 1;
    }
    Ok(v)
}
